/**
 * Quote Manager
 *
 * Loads quotes from data/quotes.json (generated by the analysis script).
 * Falls back to placeholder quotes for development.
 * Handles mood filtering, rotation, and transitions.
 */

import quotesJson from '../data/quotes.json'

export interface Quote {
  text: string
  mood: string
  date: string
  era: string
  context: string
  from_type: string
  theme?: string
  themes?: string[]
  tags?: string[]
}

export interface Theme {
  name: string
  description: string
  color_hint?: string
  quote_count?: number
}

export interface QuoteData {
  meta: { total_emails_scanned: number; total_quotes: number }
  themes: Theme[]
  timeline_narrative: string
  quotes: Quote[]
}

const data = quotesJson as QuoteData
export const THEMES: Theme[] = data.themes ?? []
export const TIMELINE_NARRATIVE: string = data.timeline_narrative ?? ''

export const MOODS = [
  'all', 'funny', 'sad', 'outrageous', 'profound',
  'mundane', 'tender', 'angry', 'absurd', 'nostalgic', 'existential',
] as const

export type Mood = typeof MOODS[number]

// Mood → color mapping for rendering
export const MOOD_COLORS: Record<string, { hue: number; sat: number; light: number }> = {
  funny:       { hue: 45,  sat: 90, light: 65 },
  sad:         { hue: 220, sat: 50, light: 55 },
  outrageous:  { hue: 350, sat: 85, light: 60 },
  profound:    { hue: 270, sat: 45, light: 60 },
  mundane:     { hue: 180, sat: 15, light: 55 },
  tender:      { hue: 330, sat: 45, light: 65 },
  angry:       { hue: 5,   sat: 75, light: 55 },
  absurd:      { hue: 160, sat: 65, light: 55 },
  nostalgic:   { hue: 35,  sat: 35, light: 55 },
  existential: { hue: 250, sat: 25, light: 55 },
}

