export const ALL_THEMES = 'all'

export class QuoteManager {
  quotes: Quote[] = []
  currentMood: Mood = 'all'
  currentTheme: string = ALL_THEMES
  currentTag: string | null = null
  currentIndex: number = 0
  private filtered: Quote[] = []

  constructor() {
    const bundled = data.quotes
    this.quotes = bundled && bundled.length > 0 ? bundled : PLACEHOLDER_QUOTES
    this.rebuildFiltered()
  }

  private shuffle() {
    for (let i = this.filtered.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[this.filtered[i], this.filtered[j]] = [this.filtered[j], this.filtered[i]]
    }
  }

  private rebuildFiltered() {
    let f = this.quotes
    if (this.currentMood !== 'all') f = f.filter(q => q.mood === this.currentMood)
    if (this.currentTheme !== ALL_THEMES) f = f.filter(q => q.theme === this.currentTheme)
    if (this.currentTag) {
      const tag = this.currentTag
      f = f.filter(q => Array.isArray(q.tags) && q.tags.includes(tag))
    }
    this.filtered = [...f]
    this.shuffle()
    this.currentIndex = 0
  }

  filterByMood(mood: Mood) {
    this.currentMood = mood
    this.rebuildFiltered()
  }

  filterByTheme(theme: string) {
    if (theme === this.currentTheme) return
    this.currentTheme = theme
    // Tag is theme-scoped; clear it when the theme changes
    this.currentTag = null
    this.rebuildFiltered()
  }

  /** Toggle a tag on/off. Pass null to clear. */
  filterByTag(tag: string | null) {
    this.currentTag = tag
    this.rebuildFiltered()
  }

  /** Tags + counts limited to the currently selected theme. */
  tagsInCurrentTheme(): Array<{ tag: string; count: number }> {
    const counts = new Map<string, number>()
    for (const q of this.quotes) {
      if (this.currentTheme !== ALL_THEMES && q.theme !== this.currentTheme) continue
      if (!Array.isArray(q.tags)) continue
      for (const t of q.tags) counts.set(t, (counts.get(t) ?? 0) + 1)
    }
    return [...counts.entries()]
      .map(([tag, count]) => ({ tag, count }))
      .sort((a, b) => b.count - a.count)
  }

  nextMood(direction: 1 | -1 = 1) {
    const idx = MOODS.indexOf(this.currentMood)
    const nextIdx = (idx + direction + MOODS.length) % MOODS.length
    this.filterByMood(MOODS[nextIdx])
  }

  current(): Quote | null {
    if (this.filtered.length === 0) return null
    return this.filtered[this.currentIndex % this.filtered.length]
  }

  next(): Quote | null {
    if (this.filtered.length === 0) return null
    this.currentIndex = (this.currentIndex + 1) % this.filtered.length
    return this.current()
  }

  get moodLabel(): string {
    return this.currentMood === 'all' ? 'all moods' : this.currentMood
  }

  get themeLabel(): string {
    return this.currentTheme === ALL_THEMES ? 'all themes' : this.currentTheme
  }

  get count(): number {
    return this.filtered.length
  }

  /**
   * Chronologically-sorted snapshot of every quote in the dataset.
   * Filters do NOT apply — time-lapse mode iterates the full archive.
   * ISO YYYY-MM-DD dates sort correctly lexicographically.
   */
  chronological(): Quote[] {
    return [...this.quotes].sort((a, b) => (a.date ?? '').localeCompare(b.date ?? ''))
  }
}

/**
 * Find the most recent quote whose date is <= targetIso (e.g. '2018-08-23').
 * Quotes must be pre-sorted by date ascending. Returns the last quote when
 * targetIso is past every entry, the first when it predates them all.
 */
export function quoteAtDate(sortedQuotes: Quote[], targetIso: string): Quote | null {
  if (sortedQuotes.length === 0) return null
  if (targetIso < sortedQuotes[0].date) return sortedQuotes[0]
  // Binary search for last index with date <= targetIso
  let lo = 0
  let hi = sortedQuotes.length - 1
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1
    if (sortedQuotes[mid].date <= targetIso) lo = mid
    else hi = mid - 1
  }
  return sortedQuotes[lo]
}
